import {uiContent as UI} from './uiContent.js';
import {siteContent as C} from './siteContent.js';
import {imageMeta as M} from './imageMeta.js';
import {videoContent as V} from './videoContent.js';
let lang=sessionStorage.getItem('miria-lang')||'en';
const t=s=>String(s).split('|')[lang==='pt'?1:0]||String(s).split('|')[0];
const img=(id,alt,cls='',eager=false)=>{const base=`/images/${String(id).padStart(2,'0')}`;return `<img class="${cls}" src="${base}${eager?'':'-thumb'}.webp" srcset="${base}-thumb.webp ${M[id].thumbWidth}w, ${base}.webp ${M[id].width}w" sizes="${id===1?'70px':eager?'(max-width: 600px) 100vw, 60vw':'(max-width: 600px) 90vw, 45vw'}" width="${M[id].width}" height="${M[id].height}" alt="${t(alt)}" loading="${eager?'eager':'lazy'}" decoding="async" ${eager?'fetchpriority="high"':''}>`};
const link=(url,label,cls='button')=>`<a class="${cls}" href="${url}">${t(label)} <span aria-hidden="true">↗</span></a>`;
const wa=()=>`https://wa.me/${C.contact.WHATSAPP_NUMBER}?text=${encodeURIComponent(t(UI.text1))}`;
function header(){return `<header><a class="brand" href="/">${img(1,'Miriã Cotrim Bridal Beauty','logo',true)}<span>Miriã Cotrim<small>BRIDAL BEAUTY</small></span></a><nav aria-label="Main navigation">${C.navigation.map((x,i)=>`<a href="${C.routes[i]}">${t(x)}</a>`).join('')}</nav><div class="header-actions"><button class="language" data-lang="${lang==='en'?'pt':'en'}" aria-label="${lang==='en'?'Mudar para português':'Switch to English'}">${lang==='en'?'<b>EN</b> / PT':'EN / <b>PT</b>'}</button>${link('/book/',UI.text2,'button small')}<button class="menu" aria-label="Open menu" aria-expanded="false">☰</button></div></header><div class="drawer" hidden>${C.navigation.map((x,i)=>`<a href="${C.routes[i]}">${t(x)}</a>`).join('')}</div>`}
function hero(){return `<section class="hero hero-film"><div class="film-background"><video id="hero-video" muted playsinline loop preload="none" poster="${V.poster}" aria-label="${t(V.label)}"></video></div><div class="hero-copy"><p class="eyebrow">${t(C.copy.eyebrow)}</p><h1>${t(C.copy.hero)}</h1><p class="hero-note">${t(UI.text3)}</p><div class="actions">${link('/book/',C.copy.book)}${link('/bridal/',C.copy.explore,'text-link')}</div></div><div class="film-bottom"><span>MIRIÃ COTRIM · BRIDAL BEAUTY</span><div><button class="film-credit" data-film-credit>${t(V.credit)}</button><button class="film-toggle" data-film-toggle aria-label="${t(V.play)}">▶ ${t(V.play)}</button></div></div></section>`}
function home(){return hero()+`<section class="intro section"><p class="eyebrow">${t(UI.text6)}</p><h2>${t(C.copy.intro)}</h2><p>${t(C.copy.introText)}</p></section>`}
function footer(){return `<footer><div class="footer-top"><div><h2>Miriã Cotrim</h2><p>BRIDAL BEAUTY</p></div><div>${C.navigation.slice(2).map((x,i)=>`<a href="${C.routes[i+2]}">${t(x)}</a>`).join('')}</div><div><a href="${C.socialMedia.instagram}" target="_blank" rel="noopener">Instagram ↗</a><a href="${C.socialMedia.facebook}" target="_blank" rel="noopener">Facebook ↗</a><a href="${wa()}" target="_blank" rel="noopener">WhatsApp ↗</a></div></div><div class="footer-bottom"><span>© ${new Date().getFullYear()} Miriã Cotrim · Concept Preview v1</span><div>${[UI.text7,UI.text8,UI.text9].map(x=>`<button data-policy="${t(x)}">${t(x)}</button>`).join('')}</div></div></footer><a class="whatsapp" href="${wa()}" target="_blank" rel="noopener" aria-label="${t(UI.text10)}"><span>◉</span> ${t(UI.text11)}</a>`}
const heading=(title,kicker='MIRIÃ COTRIM · BRIDAL BEAUTY',text='')=>`<div class="page-heading"><p class="eyebrow">${t(kicker)}</p><h1>${t(title)}</h1>${text?`<p>${t(text)}</p>`:''}</div>`;
function services(){return `<section class="section services"><div class="section-heading"><div><p class="eyebrow">${t(UI.text12)}</p><h2>${t(UI.text13)}</h2></div>${link('/services/',UI.text14,'text-link')}</div><div class="service-grid">${C.services.map((s,i)=>`<a class="service-card" href="${s[3]}"><div class="image-wrap">${img(s[2],s[0])}<span class="photo-arrow">↗</span></div><span class="number">0${i+1}</span><h3>${t(s[0])}</h3><p>${t(s[1])}</p></a>`).join('')}</div></section>`}
function bridal(compact=false){return `<section class="bridal-feature section"><div class="bridal-photo">${img(27,UI.text15)}<div class="inset-photo">${img(39,UI.text16)}</div></div><div class="bridal-copy"><p class="eyebrow">${t(UI.text17)}</p><h2>${t(UI.text18)}</h2><p>${t(UI.text19)}</p><ul class="service-list">${C.bridalServices.slice(0,compact?6:9).map(s=>`<li>${t(s)}</li>`).join('')}</ul>${link('/bridal/#inquiry',UI.text20)}</div></section>`}
function about(full=false){return `<section class="section about"><div class="about-copy"><p class="eyebrow">${t(UI.text21)}</p><h2>${t(UI.text22)}</h2><p class="roles">Bridal Beauty Artist · Hair Specialist<br>Makeup Artist · Educator</p><p>${t(C.copy.bio)}</p>${link(full?'/contact/':'/about/',full?UI.text23:UI.text24,'text-link')}</div><div class="portrait">${img(7,UI.text25)}<span class="signature">Miriã Cotrim</span></div></section>`}
const looks=[[53,UI.text26],[21,UI.text27],[41,UI.text28],[26,UI.text29],[48,UI.text30]];
function signature(){return `<section class="section signature-section"><div class="section-heading"><div><p class="eyebrow">${t(UI.text31)}</p><h2>Signature <em>Looks</em></h2></div>${link('/portfolio/',UI.text32,'text-link')}</div><div class="signature-grid">${looks.map(([id,name])=>`<button class="look" data-photo="${id}">${img(id,name)}<span>${t(name)}</span></button>`).join('')}</div></section>`}
function behind(){return `<section class="section behind"><div class="section-heading"><div><p class="eyebrow">${t(UI.text33)}</p><h2>${t(UI.text34)}</h2></div><p>${t(UI.text35)}</p></div><div class="behind-grid">${[30,31,32].map((id,i)=>`<figure>${img(id,UI.text36)}<figcaption>0${i+1} — ${t([UI.text37,UI.text38,UI.text39][i])}</figcaption></figure>`).join('')}</div><p class="process">${t(UI.text40)}</p></section>`}
let filter=0,lightIds=[],lightIndex=0;
function portfolio(){return heading(UI.text41,UI.text42,UI.text43)+`<section class="section gallery-section"><div class="filters" role="group" aria-label="${t(UI.text44)}">${C.categories.map((c,i)=>`<button data-filter="${i}" aria-pressed="${filter===i}" class="${filter===i?'active':''}">${t(c)}</button>`).join('')}</div><div class="masonry">${C.portfolio.filter(p=>!filter||p.c.includes(filter)).map(p=>`<button class="gallery-item" data-photo="${p.id}">${img(p.id,C.categories[p.c[0]])}<span>${t(C.categories[p.c[0]])} <span>↗</span></span></button>`).join('')}</div></section>`}
function openPhoto(id){lightIds=[...document.querySelectorAll('[data-photo]')].map(x=>Number(x.dataset.photo));lightIndex=lightIds.indexOf(id);drawLight();document.querySelector('#lightbox').showModal()}
function drawLight(){const id=lightIds[lightIndex],category=C.portfolio.find(x=>x.id===id);document.querySelector('#lightbox').innerHTML=`<button class="close" data-close aria-label="${t(UI.text45)}">×</button><div class="light-image">${img(id,category?C.categories[category.c[0]]:'Bridal Beauty','',true)}</div><div class="light-controls"><button data-prev>← ${t(UI.text46)}</button><span>${lightIndex+1} / ${lightIds.length} · ${t(category?C.categories[category.c[0]]:'Bridal Beauty')}</span><button data-next>${t(UI.text47)} →</button></div>`;document.querySelector('#lightbox [data-close]').onclick=()=>document.querySelector('#lightbox').close();document.querySelector('[data-prev]').onclick=()=>{lightIndex=(lightIndex+lightIds.length-1)%lightIds.length;drawLight()};document.querySelector('[data-next]').onclick=()=>{lightIndex=(lightIndex+1)%lightIds.length;drawLight()}}
const field=(label,type='text',required=true,options=[])=>`<label>${t(label)}${required?' <span aria-hidden="true">*</span>':''}${type==='select'?`<select name="${label.split('|')[0]}" ${required?'required':''}><option value="">${t(UI.text48)}</option>${options.map(x=>`<option>${t(x)}</option>`).join('')}</select>`:type==='textarea'?`<textarea name="${label.split('|')[0]}" rows="4" ${required?'required':''}></textarea>`:`<input name="${label.split('|')[0]}" type="${type}" ${type==='date'?`min="${localDate(new Date())}"`:''} ${type==='number'?'min="0" step="1"':''} ${required?'required':''}>`}</label>`;
function localDate(d){return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`}
const demo=()=>`<p class="demo-note">${t(C.copy.demo)}</p>`;
function formBlock(kind,title,fields,cta){return `<section class="section form-section" id="${kind}"><div class="form-intro"><p class="eyebrow">${t(UI.text49)}</p><h2>${t(title)}</h2><p>${t(UI.text50)}</p>${demo()}</div><form data-demo="${kind}"><div class="form-grid">${fields}</div><label class="consent"><input type="checkbox" required>${t(UI.text51)}</label><button class="button" type="submit">${t(cta)} ↗</button><div class="form-result" role="status"></div></form></section>`}
function inquiry(){return formBlock('inquiry',UI.text52,field(UI.text53)+field(UI.text54,'email')+field(UI.text55,'tel')+field(UI.text56,'date')+field(UI.text57)+field(UI.text58)+field(UI.text59,'time')+field(UI.text60,'select',true,[UI.text61,UI.text62])+field(UI.text63,'select',true,[UI.text64,UI.text65])+field(UI.text66,'number')+field(UI.text67,'number')+field(UI.text68,'number')+field(UI.text69,'select',true,[UI.text70,UI.text71,UI.text72])+field(UI.text73,'textarea',false),UI.text74)}
function academy(){return heading(UI.text75,'MIRIÃ COTRIM BEAUTY ACADEMY',UI.text76)+`<section class="section academy-intro">${img(32,UI.text77)}<div><h2>${t(UI.text78)}</h2><p>${t(UI.text79)}</p><p class="eyebrow">${t(UI.text80)}</p></div></section><section class="section course-grid">${C.academy.map((x,i)=>`<article><span class="number">0${i+1}</span><h3>${t(x)}</h3><p>${t([UI.text81,UI.text82,UI.text83,UI.text84,UI.text85][i])}</p>${link('#academy-list',UI.text86,'text-link')}</article>`).join('')}</section>`+formBlock('academy-list',UI.text87,field(UI.text88)+field(UI.text89,'tel')+field(UI.text90,'email')+field(UI.text91,'select',true,C.academy)+field(UI.text92,'textarea',false),UI.text93)}
let cart=[];
function shop(){return heading(UI.text94,UI.text95,UI.text96)+`<section class="section shop-section"><div class="shop-toolbar"><p>${t(UI.text97)}</p><button class="text-link" data-cart>${t(UI.text98)} (${cart.length})</button></div><div class="product-grid">${C.products.map((p,i)=>`<article class="product-card"><div class="product-placeholder"><span>MC</span><small>${t(UI.text99)}</small></div><p class="eyebrow">${t(UI.text100)}</p><h3>${t(p)}</h3><p>${t(UI.text101)}</p><button class="text-link" data-add="${i}">${t(UI.text102)} +</button></article>`).join('')}</div><p class="demo-note">${t(UI.text103)}</p></section>`}
function showCart(){showModal(t(UI.text104),`<div class="cart-items">${cart.length?cart.map((id,i)=>`<div><span>${t(C.products[id])}</span><button data-remove="${i}">${t(UI.text105)}</button></div>`).join(''):`<p>${t(UI.text106)}</p>`}</div><p class="demo-note">${t(UI.text107)}</p>`);document.querySelectorAll('[data-remove]').forEach(b=>b.onclick=()=>{cart.splice(Number(b.dataset.remove),1);showCart();document.querySelector('[data-cart]').textContent=`${t(UI.text108)} (${cart.length})`})}
function journal(){return heading('Beauty <em>Journal.</em>',UI.text109,UI.text110)+`<section class="section journal-grid">${C.journal.map((title,i)=>`<article>${img([26,16,21,38,53][i],title)}<p class="eyebrow">${t(UI.text111)}</p><h3>${t(title)}</h3><button class="text-link" data-article="${i}">${t(UI.text112)} ↗</button></article>`).join('')}</section>`}
function guide(){return formBlock('guide',UI.text113,field(UI.text114)+field(UI.text115,'email')+field(UI.text116,'date',false),UI.text117)}
function social(){return `<section class="section social-section"><div class="section-heading"><div><p class="eyebrow">@MIRIACOTRIM</p><h2>${t(UI.text118)}</h2></div>${link(C.socialMedia.instagram,UI.text119,'text-link')}</div><div class="social-grid">${[17,46,19,50,33,40].map(id=>`<a href="${C.socialMedia.instagram}" target="_blank" rel="noopener">${img(id,UI.text120)}</a>`).join('')}</div></section>`}
function contact(){return heading(UI.text121,UI.text122)+`<section class="section contact-layout"><div>${img(9,'Miriã Cotrim')}</div><div><p class="eyebrow">${t(UI.text123)}</p><h2>${t(UI.text124)}</h2><p>${t(UI.text125)}</p><div class="actions">${link(wa(),UI.text126)}${link('/book/',UI.text127,'text-link')}</div><p class="social-links"><a href="${C.socialMedia.instagram}">Instagram ↗</a><a href="${C.socialMedia.facebook}">Facebook ↗</a></p></div></section>`}
let step=1,booking={service:'',type:'',date:'',time:''},month=new Date(new Date().getFullYear(),new Date().getMonth(),1);
function calendar(){const start=new Date(month.getFullYear(),month.getMonth(),1).getDay(),count=new Date(month.getFullYear(),month.getMonth()+1,0).getDate(),today=localDate(new Date());return `<div class="calendar"><div class="calendar-heading"><button type="button" data-month="-1" aria-label="${t(UI.text128)}">←</button><h3>${month.toLocaleDateString(lang==='en'?'en-US':'pt-BR',{month:'long',year:'numeric'})}</h3><button type="button" data-month="1" aria-label="${t(UI.text129)}">→</button></div><div class="calendar-grid">${t(UI.text130).split(',').map(x=>`<span>${x}</span>`).join('')}${'<span></span>'.repeat(start)}${Array.from({length:count},(_,i)=>{const d=localDate(new Date(month.getFullYear(),month.getMonth(),i+1));return `<button type="button" data-date="${d}" ${d<today?'disabled':''} aria-pressed="${booking.date===d}" class="${booking.date===d?'selected':''}">${i+1}</button>`}).join('')}</div></div><div class="time-grid">${C.booking.times.map(x=>`<button type="button" data-time="${x}" aria-pressed="${booking.time===x}" class="${booking.time===x?'selected':''}">${x}</button>`).join('')}</div>`}
function book(){const titles=[UI.text131,UI.text132,UI.text133,UI.text134,UI.text135];let body='';if(step===1||step===2)body=`<div class="choice-grid">${(step===1?C.booking.services:C.booking.types).map(x=>`<button type="button" data-choice="${t(x)}" aria-pressed="${booking[step===1?'service':'type']===t(x)}" class="${booking[step===1?'service':'type']===t(x)?'selected':''}">${t(x)}</button>`).join('')}</div>`;if(step===3)body=calendar();if(step===4)body=`<div class="booking-summary">${booking.service} · ${booking.type}<br>${booking.date} · ${booking.time}</div><div class="form-grid">${field(UI.text136)+field(UI.text137,'tel')+field(UI.text138,'tel')+field(UI.text139,'email')+field(UI.text140,'date',false)+field(UI.text141,'text',false)+field(UI.text142,'number')+field(UI.text143,'textarea',false)}</div><label class="consent"><input type="checkbox" required>${t(UI.text144)}</label>`;if(step===5)body=`<div class="success"><span class="success-mark">✓</span><h2>${t(UI.text145)}</h2><p>${t(UI.text146)}</p><div class="booking-summary">${booking.service} · ${booking.date} · ${booking.time}</div>${link(wa(),UI.text147)}<button type="button" data-restart class="text-link">${t(UI.text148)}</button></div>`;return heading(UI.text149,UI.text150)+`<section class="booking-layout"><aside>${img(38,UI.text151)}<div><h3>${t(UI.text152)}</h3>${demo()}</div></aside><div class="booking-panel"><ol class="steps">${titles.map((_,i)=>`<li class="${step===i+1?'current':''}" aria-label="${t(titles[i])}" ${step===i+1?'aria-current="step"':''}>${i+1}</li>`).join('')}</ol><p class="eyebrow">${t(UI.text153)} ${step} / 5 · ${t(UI.text154)}</p><h2 class="step-title">${t(titles[step-1])}</h2><form id="booking-form">${body}<div class="booking-controls">${step>1&&step<5?`<button type="button" class="text-link" data-back>← ${t(UI.text155)}</button>`:''}${step<5?`<button class="button" type="submit">${t(step===4?UI.text156:UI.text157)} →</button>`:''}</div><p id="booking-error" role="alert"></p></form></div></section>`}
function showModal(title,body){const d=document.querySelector('#modal');d.innerHTML=`<button class="close" data-close aria-label="${t(UI.text158)}">×</button><h2>${title}</h2>${body}`;if(!d.open)d.showModal();d.querySelector('[data-close]').onclick=()=>d.close()}
function fullHome(){return home()+services()+bridal(true)+signature()+about()+behind()+`<section class="client-love section"><p class="eyebrow">${t(UI.text159)}</p><h2>${t(UI.text160)}</h2><p>${t(UI.text161)}</p></section>`+guide()+social()}
function servicesPage(){return heading(UI.text162)+services()+`<section class="section service-details"><article id="events"><p class="eyebrow">SPECIAL EVENTS</p><h2>${t(UI.text163)}</h2><p>${t(UI.text164)}</p>${link('/book/',C.copy.book)}</article><article id="hair"><p class="eyebrow">HAIR SERVICES</p><h2>${t(UI.text165)}</h2><p>${t(UI.text166)}</p>${link(wa(),UI.text167)}</article></section>`}
function render(){document.documentElement.lang=lang;const route=location.pathname.split('/').filter(Boolean)[0]||'home';const pages={home:fullHome,about:()=>heading(UI.text168)+about(true)+behind(),services:servicesPage,bridal:()=>heading(UI.text169)+bridal()+inquiry(),portfolio,academy,shop,journal,contact,book};document.title=`${t(C.navigation[C.routes.findIndex(x=>x==='/'+route+'/')]||'Bridal Beauty')} | Miriã Cotrim`;document.querySelector('#app').innerHTML=header()+`<main>${(pages[route]||fullHome)()}</main>`+footer();document.querySelector('.footer-top').insertAdjacentHTML('beforeend',`<div class="footer-newsletter"><h3>${t(UI.text170)}</h3><form data-demo="newsletter"><div class="form-grid">${field(UI.text171)+field(UI.text172,'email')}</div><p class="demo-note">${t(UI.text173)}</p><button type="submit" class="button small">${t(UI.text174)} ↗</button><div class="form-result" role="status"></div></form></div>`);bind();}
function bind(){document.querySelector('[data-lang]').onclick=()=>{lang=lang==='en'?'pt':'en';sessionStorage.setItem('miria-lang',lang);if(step<5){step=1;booking={service:'',type:'',date:'',time:''}}render()};document.querySelector('.menu').onclick=e=>{const d=document.querySelector('.drawer');d.hidden=!d.hidden;e.currentTarget.setAttribute('aria-expanded',String(!d.hidden));e.currentTarget.textContent=d.hidden?'☰':'×'};document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{filter=Number(b.dataset.filter);const y=scrollY;render();scrollTo(0,y)});document.querySelectorAll('[data-photo]').forEach(b=>b.onclick=()=>openPhoto(Number(b.dataset.photo)));document.querySelectorAll('[data-demo]').forEach(f=>f.onsubmit=e=>{e.preventDefault();f.querySelector('.form-result').innerHTML=`<strong>${t(UI.text175)}</strong><p>${t(f.dataset.demo==='guide'?UI.text176:UI.text177)}</p>${link(wa(),UI.text178,'text-link')}`;f.querySelector('.form-result').scrollIntoView({block:'center',behavior:'smooth'})});document.querySelectorAll('[data-policy]').forEach(b=>b.onclick=()=>showModal(b.dataset.policy,`<p>${t(UI.text179)}</p>${link(wa(),UI.text180,'text-link')}`));document.querySelectorAll('[data-article]').forEach(b=>b.onclick=()=>showModal(t(C.journal[Number(b.dataset.article)]),`<p>${t(UI.text181)}</p>${link(wa(),UI.text182,'text-link')}`));document.querySelectorAll('[data-add]').forEach(b=>b.onclick=()=>{cart.push(Number(b.dataset.add));b.textContent=t(UI.text183);document.querySelector('[data-cart]').textContent=`${t(UI.text184)} (${cart.length})`});document.querySelector('[data-cart]')?.addEventListener('click',showCart);bindBooking();}
function bindBooking(){const f=document.querySelector('#booking-form');if(!f)return;document.querySelectorAll('[data-choice]').forEach(b=>b.onclick=()=>{booking[step===1?'service':'type']=b.dataset.choice;document.querySelectorAll('[data-choice]').forEach(x=>{x.classList.toggle('selected',x===b);x.setAttribute('aria-pressed',String(x===b))})});document.querySelectorAll('[data-month]').forEach(b=>b.onclick=()=>{month=new Date(month.getFullYear(),month.getMonth()+Number(b.dataset.month),1);const y=scrollY;render();scrollTo(0,y)});document.querySelectorAll('[data-date]').forEach(b=>b.onclick=()=>{booking.date=b.dataset.date;document.querySelectorAll('[data-date]').forEach(x=>{x.classList.toggle('selected',x===b);x.setAttribute('aria-pressed',String(x===b))})});document.querySelectorAll('[data-time]').forEach(b=>b.onclick=()=>{booking.time=b.dataset.time;document.querySelectorAll('[data-time]').forEach(x=>{x.classList.toggle('selected',x===b);x.setAttribute('aria-pressed',String(x===b))})});document.querySelector('[data-back]')?.addEventListener('click',()=>{step--;render();document.querySelector('.booking-panel').scrollIntoView({block:'start'})});document.querySelector('[data-restart]')?.addEventListener('click',()=>{step=1;booking={service:'',type:'',date:'',time:''};render()});f.onsubmit=e=>{e.preventDefault();if((step===1&&!booking.service)||(step===2&&!booking.type)||(step===3&&(!booking.date||!booking.time))){document.querySelector('#booking-error').textContent=t(UI.text185);return}step++;render();document.querySelector('.booking-panel').scrollIntoView({block:'start',behavior:'smooth'})}}
document.querySelector('#lightbox').addEventListener('keydown',e=>{if(e.key==='ArrowRight')document.querySelector('[data-next]')?.click();if(e.key==='ArrowLeft')document.querySelector('[data-prev]')?.click()});
function bindHero(){const v=document.querySelector('#hero-video');if(!v)return;const b=document.querySelector('[data-film-toggle]');let manuallyPaused=false;const prefersStill=matchMedia('(prefers-reduced-motion: reduce)').matches||navigator.connection?.saveData;const setSource=()=>{if(!v.getAttribute('src')){v.src=matchMedia('(max-width: 600px)').matches?V.mobile:V.desktop;v.load()}};const update=()=>{b.textContent=(v.paused?'▶ ':'Ⅱ ')+t(v.paused?V.play:V.pause);b.setAttribute('aria-label',t(v.paused?V.play:V.pause))};v.addEventListener('play',update);v.addEventListener('pause',update);v.addEventListener('error',()=>{v.removeAttribute('src');v.load();update()});b.onclick=()=>{if(v.paused){manuallyPaused=false;setSource();v.play().catch(update)}else{manuallyPaused=true;v.pause()}};document.querySelector('[data-film-credit]').onclick=()=>showModal(t(V.label),`<p>${t(V.note)}</p><ul class="film-sources">${V.sources.map(s=>`<li><a href="${s.url}" target="_blank" rel="noopener">${s.title} — ${s.author} ↗</a></li>`).join('')}</ul><a class="text-link" href="${V.license}" target="_blank" rel="noopener">Pexels License ↗</a>`);if(!prefersStill){setSource();v.play().catch(update)}const observer=new IntersectionObserver(entries=>{if(!v.isConnected){observer.disconnect();return}if(!entries[0].isIntersecting)v.pause();else if(!prefersStill&&!manuallyPaused&&v.getAttribute('src'))v.play().catch(update)},{threshold:.1});observer.observe(v);}
const originalBind=bind;bind=function(){originalBind();bindHero();document.querySelector('.menu').setAttribute('aria-label',lang==='pt'?'Abrir menu':'Open menu');};
render();
